s=s.replace('''import { envelope, orgResource, requireFound } from "./_support";''','''import { actorEnvelope, envelope, orgResource, requireFound } from "./_support";''')
s=s.replace('''  DeleteOrganizationInput,
  UpdateOrganizationInput,''','''  DeleteOrganizationInput,
