new='''/**
 * Changes the workspace URL (ADR 0005). The slug is taken exactly as typed —
 * never suffixed — and refused with `InvalidSlugError` when it is malformed,
 * reserved or unavailable. The old slug is retired and keeps resolving to this
 * workspace for `ORG_SLUG_HOLD_DAYS` days.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug === input.slug) return org;

  assertValidSlug(input.slug);
  if (!(await orgRepo.isOrgSlugAvailable(org.id, input.slug))) {
    throw new InvalidSlugError(input.slug, "is not available");
  }

  const from = org.slug;
  const updated = await orgRepo.renameOrgSlug(org.id, from, input.slug);

  await emit("organization.slug_changed", {
    ...actorEnvelope(actor),
    from,
    to: updated.slug,
  });

  await record(org.id, "organization.slug_changed", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: org.id,
    projectId: null,
    summary: `Workspace URL changed from ${from} to ${updated.slug}`,
    metadata: { from, to: updated.slug },
  });

  return updated;
}

