cd /private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/06a229d1-1c07-45c6-8771-5f22a0cf3083; cat > tests/zz-tmp-rename.test.ts <<'EOF'
import { describe, expect, it, vi } from "vitest";
import { subscribe } from "@/lib/event-bus";
import * as orgRepo from "@/server/repositories/organization-repository";
import { renameOrganizationSlug, createOrganization } from "@/server/services/organization-service";
import { listActivity } from "@/server/services/activity-service";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";

describe("tmp", () => {
  it("renames", async () => {
    const cleanup = await useTemporaryDatabase();
    const a = await createTenant("acme", "growth");
    const b = await createTenant("globex", "growth");
    const seen: unknown[] = [];
    const off = subscribe("organization.slug_changed", (p) => { seen.push(p); });
    const r = await renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "acme-two" });
    expect(r.slug).toBe("acme-two");
    expect((await orgRepo.findOrgBySlug("acme"))?.id).toBe(a.org.id);
    await expect(renameOrganizationSlug(b.actors.owner, { orgId: b.org.id, slug: "acme" })).rejects.toThrow();
    await renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "acme-two" });
    expect(seen).toHaveLength(1);
    const page = await listActivity(a.actors.owner, { orgId: a.org.id, action: ["organization.slug_changed"], limit: 10, cursor: null } as never);
    expect(page.items).toHaveLength(1);
    expect(page.items[0]?.metadata).toEqual({ from: "acme", to: "acme-two" });
    vi.useFakeTimers();
    vi.setSystemTime(Date.now() + 30 * 86400000);
    expect(await orgRepo.findOrgBySlug("acme")).toBeNull();
    const r2 = await renameOrganizationSlug(b.actors.owner, { orgId: b.org.id, slug: "acme" });
    expect(r2.slug).toBe("acme");
    vi.useRealTimers();
    off(); cleanup();
  });
});
EOF
npx vitest run tests/zz-tmp-rename.test.ts 2>&1 | grep -v "npm warn" | tail -30; rm tests/zz-tmp-rename.test.ts

